<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\{Csrf,Request,Response,View};use App\Repositories\UserRepository;use App\Security\Auth;
final readonly class UserController{public function __construct(private View $view,private UserRepository $repo,private Csrf $csrf){}public function index(Request $r):void{$this->deny();$this->view->render('users/index',['title'=>'Usuarios','users'=>$this->repo->all(),'groups'=>$this->repo->groups(),'csrf'=>$this->csrf]);}public function store(Request $r):void{$this->deny();$email=trim($r->string('email'));$name=trim($r->string('name'));if(!preg_match('/^[A-Za-z0-9._-]{3,120}$/',$name)||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||strlen($r->string('password'))<12||$r->int('group_id')<1){http_response_code(422);exit('Datos inválidos');}$this->repo->create($name,$email!==''?strtolower($email):null,$r->string('password'),$r->int('group_id'));Response::redirect('/users');}public function status(Request $r):void{$this->deny();$id=$r->int('id');$status=$r->string('status');if($id===Auth::id()||!in_array($status,['active','suspended','blocked'],true)){http_response_code(422);exit('No puedes bloquear tu propia sesión o el estado es inválido.');}$this->repo->status($id,$status);Response::redirect('/users');}private function deny():void{if(!Auth::can('users.manage')){http_response_code(403);exit('Sin permiso');}}}
